-- P5: full-text search over messages with no new dependency.
-- The tsvector is generated by Postgres, so it can never drift from body and
-- an existing message needs no application-side reindex.
ALTER TABLE messages
    ADD COLUMN search_vector tsvector
    GENERATED ALWAYS AS (to_tsvector('indonesian'::regconfig, body)) STORED;

CREATE INDEX messages_search_idx ON messages USING GIN (search_vector);
